import android.app.*; import android.content.*; import android.graphics.Color; import android.graphics.drawable.GradientDrawable; import android.os.*; import android.provider.Settings; import android.view.*; import android.widget.*;
public class LoveOverlayService extends Service { WindowManager wm; View v; public IBinder onBind(Intent i){return null;} public int onStartCommand(Intent i,int f,int s){show(); return START_NOT_STICKY;} void show(){if(v!=null)return; wm=(WindowManager)getSystemService(WINDOW_SERVICE); LinearLayout box=new LinearLayout(this); box.setOrientation(LinearLayout.VERTICAL); box.setGravity(Gravity.CENTER); box.setPadding(35,22,35,22); GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xffff9fbe,0xffffd6e7}); bg.setCornerRadius(35); box.setBackground(bg); TextView x=new TextView(this); x.setText("♥  ♥  ♥\nAKU SAYANG KAMU\nMIA SAYANG\n♥  Selalu di hatiku  ♥"); x.setGravity(Gravity.CENTER); x.setTextColor(0xffb51f55); x.setTextSize(30); x.setTypeface(null,1); box.addView(x); box.setOnClickListener(q->stopSelf()); v=box; int type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE; WindowManager.LayoutParams p=new WindowManager.LayoutParams(-2,-2,type,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,-3); p.gravity=Gravity.CENTER; wm.addView(v,p); } public void onDestroy(){if(v!=null){wm.removeView(v);v=null;}super.onDestroy();}}
